package dispatch;
import dispatch.app.Desk;
import dispatch.infra.MemoryDispatches;
import dispatch.infra.StandardRenderer;
import dispatch.ports.DeskApi;
import dispatch.ports.NoticeSink;
/** The composition root chooses concrete adapters. */
public final class Composition {
    private Composition() {}
    public static DeskApi create(NoticeSink sink) {
        return new Desk(new MemoryDispatches(),new StandardRenderer(),sink);
    }
}

package dispatch.app;
import dispatch.domain.Dispatch;
import dispatch.domain.Request;
import dispatch.ports.DeskApi;
import dispatch.ports.DispatchRepository;
import dispatch.ports.NoticeSink;
import dispatch.ports.Renderer;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
/** The service owns send ordering and the guard; adapters own rendering and storage. */
public final class Desk implements DeskApi {
    private final DispatchRepository repository;
    private final Renderer renderer;
    private final NoticeSink sink;
    private boolean busy;
    public Desk(DispatchRepository repository,Renderer renderer,NoticeSink sink) {
        this.repository=Objects.requireNonNull(repository,"repository");
        this.renderer=Objects.requireNonNull(renderer,"renderer");
        this.sink=Objects.requireNonNull(sink,"sink");
    }
    public Dispatch preview(Request request) {
        Objects.requireNonNull(request,"request");
        Dispatch result=Objects.requireNonNull(renderer.render(request),"rendered dispatch");
        if(!result.id().equals(request.id()))throw new IllegalArgumentException("renderer changed id");
        return result;
    }
    public Dispatch send(Request request) {
        if(busy)throw new IllegalStateException("reentrant send");
        busy=true;
        try {
            Objects.requireNonNull(request,"request");
            if(repository.find(request.id()).isPresent())throw new IllegalArgumentException("duplicate id");
            Dispatch result=preview(request);
            repository.insert(result);
            sink.sent(result);
            return result;
        } finally { busy=false; }
    }
    public Optional<Dispatch> find(String id) { return repository.find(Request.key(id)); }
    public List<Dispatch> all() { return List.copyOf(repository.all()); }
    public List<Dispatch> sendBatch(List<Request> requests) {
        if(busy)throw new IllegalStateException("reentrant send");
        List<Request> selected=List.copyOf(Objects.requireNonNull(requests,"requests"));
        List<Dispatch> result=new ArrayList<>();
        for(Request request:selected)result.add(send(request));
        return List.copyOf(result);
    }
}

package dispatch.domain;
/** Stored outcome; immutable strings and primitive values have no mutable aliases. */
public record Dispatch(String id,String rendered,int cents) {
    public Dispatch {
        id=Request.key(id);rendered=Request.line(rendered);
        if(cents<0)throw new IllegalArgumentException("nonnegative cents");
    }
}

package dispatch.domain;
import java.util.Objects;
/** One bounded, immutable dispatch request; all monetary values are teaching cents. */
public record Request(String id,String text,Channel channel,Priority priority,int copies) {
    public enum Channel { EMAIL, SMS }
    public enum Priority { NORMAL, URGENT }
    public Request {
        id=key(id);text=line(text);
        Objects.requireNonNull(channel,"channel");Objects.requireNonNull(priority,"priority");
        if(copies<1 || copies>20)throw new IllegalArgumentException("copies must be 1..20");
    }
    public static String key(String value) {
        Objects.requireNonNull(value,"id");
        if(!value.matches("[a-z][a-z0-9-]*"))throw new IllegalArgumentException("invalid id");
        return value;
    }
    public static String line(String value) {
        Objects.requireNonNull(value,"text");
        if(value.indexOf('\r')>=0 || value.indexOf('\n')>=0)throw new IllegalArgumentException("single-line text");
        return value;
    }
}

package dispatch.infra;
import dispatch.domain.Dispatch;
import dispatch.domain.Request;
import dispatch.ports.DispatchRepository;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
public final class MemoryDispatches implements DispatchRepository {
    private final LinkedHashMap<String,Dispatch> sent=new LinkedHashMap<>();
    public Optional<Dispatch> find(String id) { return Optional.ofNullable(sent.get(Request.key(id))); }
    public List<Dispatch> all() { return List.copyOf(sent.values()); }
    public void insert(Dispatch dispatch) {
        Objects.requireNonNull(dispatch,"dispatch");
        if(sent.containsKey(dispatch.id()))throw new IllegalArgumentException("duplicate id");
        sent.put(dispatch.id(),dispatch);
    }
}

package dispatch.infra;
import dispatch.domain.Dispatch;
import dispatch.domain.Request;
import dispatch.ports.Renderer;
import java.util.Objects;
/** A closed pair of channels stays an explicit switch instead of a speculative factory hierarchy. */
public final class StandardRenderer implements Renderer {
    public Dispatch render(Request request) {
        Objects.requireNonNull(request,"request");
        String prefix=switch(request.channel()) { case EMAIL -> "EMAIL: "; case SMS -> "SMS: "; };
        int unit=switch(request.channel()) { case EMAIL -> 100; case SMS -> 60; };
        if(request.priority()==Request.Priority.URGENT) { prefix="URGENT "+prefix;unit+=40; }
        return new Dispatch(request.id(),prefix+request.text(),unit*request.copies());
    }
}

package dispatch.legacy;
import dispatch.domain.Dispatch;
import dispatch.domain.Request;
import dispatch.ports.DeskApi;
import dispatch.ports.NoticeSink;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
/** Preserved runnable baseline: rendering, rates, storage and orchestration are coupled. */
public final class LegacyDesk implements DeskApi {
    private final LinkedHashMap<String,Dispatch> sent=new LinkedHashMap<>();
    private final NoticeSink sink;
    private boolean busy;
    public LegacyDesk(NoticeSink sink) { this.sink=Objects.requireNonNull(sink,"sink"); }
    public Dispatch preview(Request request) {
        Objects.requireNonNull(request,"request");
        String rendered;
        int unit;
        if(request.channel()==Request.Channel.EMAIL) {
            rendered="EMAIL: "+request.text();
            unit=100;
        } else {
            rendered="SMS: "+request.text();
            unit=60;
        }
        if(request.priority()==Request.Priority.URGENT) {
            rendered="URGENT "+rendered;
            unit+=40;
        }
        return new Dispatch(request.id(),rendered,unit*request.copies());
    }
    public Dispatch send(Request request) {
        if(busy)throw new IllegalStateException("reentrant send");
        busy=true;
        try {
            Objects.requireNonNull(request,"request");
            if(sent.containsKey(request.id()))throw new IllegalArgumentException("duplicate id");
            String rendered;
            int unit;
            if(request.channel()==Request.Channel.EMAIL) {
                rendered="EMAIL: "+request.text();
                unit=100;
            } else {
                rendered="SMS: "+request.text();
                unit=60;
            }
            if(request.priority()==Request.Priority.URGENT) {
                rendered="URGENT "+rendered;
                unit+=40;
            }
            Dispatch result=new Dispatch(request.id(),rendered,unit*request.copies());
            sent.put(result.id(),result);
            sink.sent(result);
            return result;
        } finally { busy=false; }
    }
    public Optional<Dispatch> find(String id) { return Optional.ofNullable(sent.get(Request.key(id))); }
    public List<Dispatch> all() { return List.copyOf(sent.values()); }
}

package dispatch.ports;
import dispatch.domain.Dispatch;
import dispatch.domain.Request;
import java.util.List;
