    Dispatch send(Request request);
    Optional<Dispatch> find(String id);
    List<Dispatch> all();
    default List<Dispatch> sendBatch(List<Request> requests) {
        throw new UnsupportedOperationException("Implement optional prefix-commit batch.");
    }
}

